public static class Program
{
    public static async Task<object?> SignIn(object? request, object? deps = null)
    {
        var __f = FddVerify.Frame("bp-auth-login");
        __f.Enter("NODE-AUTH-LOGIN-001");
        object? email = request.Get("body").Get("email");
        object? emailCheck = CheckEmail(email, "email");
        object? password = request.Get("body").Get("password");
        __f.Enter("NODE-AUTH-LOGIN-006");
        if (!(B(emailCheck.Get("valid")) && !IsEmpty(password)))
        {
            __f.Enter("NODE-AUTH-LOGIN-009");
            return Obj(
                ("status", 401d),
                ("body", Obj(
                    ("error", B(emailCheck.Get("valid")) ? (object?)CheckRequired(password, "password").Get("message") : emailCheck.Get("message")))));
        }
        __f.Enter("NODE-AUTH-LOGIN-010");
        object? lookUpUser = await FddVerify.Dep("userService", "getUsersByEmail", "NODE-AUTH-LOGIN-010", Obj(("query", OmitNulls(Obj(("email", email))))));
        switch (lookUpUser.Get("status"))
        {
            case 200d:
            {
                __f.Enter("NODE-AUTH-LOGIN-014");
                if (!Eq(lookUpUser.Get("body").Get("passwordHash"), Format("hash:{password}", Obj(("password", password)))))
                {
                    __f.Enter("NODE-AUTH-LOGIN-021");
                    return Obj(("status", 401d), ("body", Obj(("error", "Invalid credentials"))));
                }
                object? id = lookUpUser.Get("body").Get("id");
                __f.Enter("NODE-AUTH-LOGIN-018");
                await FddVerify.Dep("eventBus", "publishUserLoggedIn", "NODE-AUTH-LOGIN-018", Obj(("userId", id)));
                __f.Enter("NODE-AUTH-LOGIN-019");
                return Obj(
                    ("status", 200d),
                    ("body", Obj(
                        ("accessToken", Format("TEST-TOKEN-{id}", Obj(("id", id)))),
                        ("refreshToken", "REFRESH-TOKEN"),
                        ("expiresIn", 3600d),
                        ("tokenType", "Bearer"))));
            }
            case 404d:
            {
                __f.Enter("NODE-AUTH-LOGIN-022");
                return Obj(("status", 401d), ("body", Obj(("error", "Invalid credentials"))));
            }
            default:
            {
                __f.Enter("NODE-AUTH-LOGIN-023");
                throw new FddError("UPSTREAM_ERROR", "User Service failed");
            }
        }
    }
}

