// Runtime for code generated by Rabbinatix from Logic Blueprints. Do not edit: it is regenerated on export.
// Every helper mirrors the simulator, so generated handlers behave exactly like their blueprints.
// Values are JSON values: Dictionary<string, object?>, List<object?>, string, double, bool and null.
#nullable enable
using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using System.Text;
using System.Text.Json;
using System.Text.RegularExpressions;
using System.Threading.Tasks;

namespace FddCheck;

/// <summary>An error with a code, like the simulator's errors (Throw nodes, DIVIDE_BY_ZERO, INVALID_JSON…).</summary>
public sealed class FddError : Exception
{
    public string Code { get; }

    public FddError(object? code, object? message) : base(FddRuntime.AsString(message)) => Code = FddRuntime.AsString(code);
}

/// <summary>Converts between your own types and the JSON values the handlers take and return.</summary>
public static class FddJson
{
    public static object? ToValue<T>(T value) => FromElement(JsonSerializer.SerializeToElement(value));

    public static T? FromValue<T>(object? value) => JsonSerializer.Deserialize<T>(FddRuntime.Json(value));

    public static object? Parse(string json)
    {
        using var doc = JsonDocument.Parse(json);
        return FromElement(doc.RootElement);
    }

    public static string Stringify(object? value) => FddRuntime.Json(value);

    public static object? FromElement(JsonElement e) => e.ValueKind switch
    {
        JsonValueKind.Object => e.EnumerateObject().Aggregate(new Dictionary<string, object?>(), (d, p) => { d[p.Name] = FromElement(p.Value); return d; }),
        JsonValueKind.Array => e.EnumerateArray().Select(FromElement).ToList(),
        JsonValueKind.String => e.GetString(),
        JsonValueKind.Number => e.GetDouble(),
        JsonValueKind.True => true,
        JsonValueKind.False => false,
        _ => null,
    };
}

public static class FddRuntime
{
    static readonly CultureInfo Inv = CultureInfo.InvariantCulture;
    static readonly Random Rng = new();

    // ---------- the value model the generated code uses ----------

    /// <summary>A condition: true only for true, else JavaScript truthiness.</summary>
    public static bool B(object? v) => v is bool b ? b : Truthy(v);

    /// <summary>A number operand.</summary>
    public static double N(object? v) => v is double d ? d : ToNum(v);

    /// <summary>o.name, null-safe: null when o is null or has no such field.</summary>
    public static object? Get(this object? o, string name) => Key(o, name);

    /// <summary>o[key], null-safe.</summary>
    public static object? Item(this object? o, object? key) => Key(o, key);

    public static Dictionary<string, object?> Obj(params (string Key, object? Value)[] fields)
    {
        var d = new Dictionary<string, object?>();
        foreach (var (k, v) in fields) d[k] = v;
        return d;
    }

    public static List<object?> Arr(params object?[] items) => new(items);

    /// <summary>a === b for strings, numbers, booleans and null.</summary>
    public static bool Eq(object? a, object? b) => a switch
    {
        null => b is null,
        double x => b is double y && x == y,
        string s => b is string t && string.Equals(s, t, StringComparison.Ordinal),
        bool p => b is bool q && p == q,
        _ => ReferenceEquals(a, b),
    };

    public static IEnumerable<object?> Iter(object? v) => v as List<object?> ?? new List<object?>();

    public static IEnumerable<(object? Index, object? Item)> Indexed(object? v) => Iter(v).Select((x, i) => ((object?)(double)i, x));

    public static List<object?> Map(object? items, Func<object?, object?, object?> fn) => AsArray(items).Select((x, i) => fn(x, (double)i)).ToList();

    public static List<object?> Filter(object? items, Func<object?, object?, bool> fn) => AsArray(items).Where((x, i) => fn(x, (double)i)).ToList();

    public static object? Find(object? items, Func<object?, object?, bool> fn)
    {
        var list = AsArray(items);
        for (var i = 0; i < list.Count; i++) if (fn(list[i], (double)i)) return list[i];
        return null;
    }

    public static bool Some(object? items, Func<object?, object?, bool> fn)
    {
        var list = AsArray(items);
        for (var i = 0; i < list.Count; i++) if (fn(list[i], (double)i)) return true;
        return false;
    }

    public static bool Every(object? items, Func<object?, object?, bool> fn)
    {
        var list = AsArray(items);
        for (var i = 0; i < list.Count; i++) if (!fn(list[i], (double)i)) return false;
        return true;
    }

    static object? Key(object? o, object? k)
    {
        switch (o)
        {
            case Dictionary<string, object?> d:
                return d.TryGetValue(k as string ?? AsString(k), out var v) ? v : null;
            case List<object?> l:
                if (k is "length") return (double)l.Count;
                if (Index(k) is int i && i < l.Count) return l[i];
                return null;
            case string s:
                if (k is "length") return (double)s.Length;
                if (Index(k) is int j && j < s.Length) return s[j].ToString();
                return null;
            default:
                return null;
        }
    }

    static int? Index(object? k)
    {
        var d = k is double x ? x : k is string s && s.Length > 0 && s.All(char.IsAsciiDigit) ? double.Parse(s, Inv) : double.NaN;
        return d >= 0 && d < int.MaxValue && Math.Floor(d) == d ? (int)d : null;
    }

    // ---------- JavaScript conversions ----------

    /// <summary>A number as JavaScript's String(n) writes it.</summary>
    public static string NumText(double n)
    {
        if (double.IsNaN(n)) return "NaN";
        if (double.IsInfinity(n)) return n > 0 ? "Infinity" : "-Infinity";
        if (n == 0) return "0";
        var r = Math.Abs(n).ToString("R", Inv);
        var exp = 0;
        var e = r.IndexOfAny(new[] { 'E', 'e' });
        if (e >= 0) { exp = int.Parse(r[(e + 1)..], Inv); r = r[..e]; }
        var dot = r.IndexOf('.');
        var digits = r.Replace(".", "");
        var point = (dot < 0 ? r.Length : dot) + exp;
        var lead = digits.Length - digits.TrimStart('0').Length;
        digits = digits.TrimStart('0');
        point -= lead;
        digits = digits.TrimEnd('0');
        if (digits.Length == 0) digits = "0";
        var k = digits.Length;
        var sign = n < 0 ? "-" : "";
        if (k <= point && point <= 21) return sign + digits + new string('0', point - k);
        if (0 < point && point <= 21) return sign + digits[..point] + "." + digits[point..];
        if (-6 < point && point <= 0) return sign + "0." + new string('0', -point) + digits;
        var x = point - 1;
        return sign + digits[0] + (k > 1 ? "." + digits[1..] : "") + "e" + (x >= 0 ? "+" : "-") + Math.Abs(x).ToString(Inv);
    }

    /// <summary>String(v).</summary>
    public static string JsString(object? v) => v switch
    {
        null => "null",
        bool b => b ? "true" : "false",
        double d => NumText(d),
        string s => s,
        List<object?> l => string.Join(",", l.Select(x => x is null ? "" : JsString(x))),
        Dictionary<string, object?> => "[object Object]",
        _ => Convert.ToString(v, Inv) ?? "",
    };

    /// <summary>JSON.stringify.</summary>
    public static string Json(object? v)
    {
        var sb = new StringBuilder();
        Write(sb, v);
        return sb.ToString();
    }

    static void Write(StringBuilder sb, object? v)
    {
        switch (v)
        {
            case null: sb.Append("null"); break;
            case bool b: sb.Append(b ? "true" : "false"); break;
            case double d: sb.Append(double.IsFinite(d) ? NumText(d) : "null"); break;
            case string s: Quote(sb, s); break;
            case List<object?> l:
                sb.Append('[');
                for (var i = 0; i < l.Count; i++) { if (i > 0) sb.Append(','); Write(sb, l[i]); }
                sb.Append(']');
                break;
            case Dictionary<string, object?> d:
                sb.Append('{');
                var first = true;
                foreach (var (k, x) in d) { if (!first) sb.Append(','); first = false; Quote(sb, k); sb.Append(':'); Write(sb, x); }
                sb.Append('}');
                break;
            default: Quote(sb, Convert.ToString(v, Inv) ?? ""); break;
        }
    }

    static void Quote(StringBuilder sb, string s)
    {
        sb.Append('"');
        foreach (var c in s)
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                default:
                    if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4", Inv));
                    else sb.Append(c);
                    break;
            }
        }
        sb.Append('"');
    }

    static readonly Regex Decimal = new(@"^[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?$", RegexOptions.CultureInvariant);

    /// <summary>Number(v).</summary>
    public static double JsNumber(object? v)
    {
        switch (v)
        {
            case null: return 0;
            case bool b: return b ? 1 : 0;
            case double d: return d;
            case string s:
                var t = s.Trim().Trim('﻿');
                if (t.Length == 0) return 0;
                if (t.Length > 2 && t[0] == '0' && "xXoObB".Contains(t[1]))
                {
                    var radix = char.ToLowerInvariant(t[1]) switch { 'x' => 16, 'o' => 8, _ => 2 };
                    var acc = 0d;
                    foreach (var ch in t[2..])
                    {
                        var dgt = char.IsAsciiDigit(ch) ? ch - '0' : char.IsAsciiLetter(ch) ? char.ToLowerInvariant(ch) - 'a' + 10 : 99;
                        if (dgt >= radix) return double.NaN;
                        acc = acc * radix + dgt;
                    }
                    return acc;
                }
                if (t is "Infinity" or "+Infinity") return double.PositiveInfinity;
                if (t == "-Infinity") return double.NegativeInfinity;
                return Decimal.IsMatch(t) ? double.Parse(t, NumberStyles.Float, Inv) : double.NaN;
            case List<object?> l:
                return l.Count == 0 ? 0 : l.Count == 1 && l[0] is not (List<object?> or Dictionary<string, object?>) ? JsNumber(l[0] ?? "") : double.NaN;
            default: return double.NaN;
        }
    }

    static bool Lt(object? a, object? b)
    {
        if (a is string s && b is string t) return string.CompareOrdinal(s, t) < 0;
        static object? Prim(object? x) => x is List<object?> or Dictionary<string, object?> ? JsString(x) : x;
        return JsNumber(Prim(a)) < JsNumber(Prim(b));
    }

    // ---------- values ----------

    /// <summary>Branch semantics: "" and "false" are false.</summary>
    public static bool Truthy(object? v) => v switch
    {
        null => false,
        string s => s != "" && s != "false",
        bool b => b,
        double d => d != 0 && !double.IsNaN(d),
        _ => true,
    };

    /// <summary>null, "", [] or {}.</summary>
    public static bool IsEmpty(object? v) => v switch
    {
        null => true,
        string s => s.Trim().Length == 0,
        List<object?> l => l.Count == 0,
        Dictionary<string, object?> d => d.Count == 0,
        _ => false,
    };

    /// <summary>null or missing.</summary>
    public static bool IsNull(object? v) => v is null;

    /// <summary>Structural equality (objects and arrays by value).</summary>
    public static bool DeepEqual(object? a, object? b)
    {
        if (a is double x && b is double y) return x == y || (double.IsNaN(x) && double.IsNaN(y));
        if (a is List<object?> l && b is List<object?> m) return l.Count == m.Count && l.Zip(m).All(p => DeepEqual(p.First, p.Second));
        if (a is Dictionary<string, object?> d && b is Dictionary<string, object?> e) return d.Count == e.Count && d.All(p => e.TryGetValue(p.Key, out var q) && DeepEqual(p.Value, q));
        return Eq(a, b);
    }

    /// <summary>-1, 0 or 1.</summary>
    public static double Compare(object? a, object? b) => DeepEqual(a, b) ? 0 : Lt(a, b) ? -1 : 1;

    /// <summary>Arithmetic operand: numbers as is, anything else through Number().</summary>
    public static double ToNum(object? v) => v is double d ? d : JsNumber(v ?? 0d);

    /// <summary>Division that fails on zero.</summary>
    public static double Divide(object? a, object? b)
    {
        if (ToNum(b) == 0) throw new FddError("DIVIDE_BY_ZERO", "Division by zero");
        return ToNum(a) / ToNum(b);
    }

    /// <summary>The value if it is an array, else [].</summary>
    public static List<object?> AsArray(object? v) => v as List<object?> ?? new List<object?>();

    /// <summary>A query found something (not null, not an empty list).</summary>
    public static bool IsFound(object? v) => v is not null && !(v is List<object?> l && l.Count == 0);

    /// <summary>Drops null entries (query and header maps).</summary>
    public static Dictionary<string, object?> OmitNulls(object? o) =>
        (o as Dictionary<string, object?> ?? new()).Where(p => p.Value is not null).ToDictionary(p => p.Key, p => p.Value);

    // ---------- paths & objects ----------

    static readonly Regex Segment = new(@"([^\[\]]+)|\[(\d+)\]", RegexOptions.CultureInvariant);

    /// <summary>user.roles[0].name → segments.</summary>
    public static List<object> PathSegments(string path)
    {
        var out_ = new List<object>();
        foreach (var part in path.Split('.', StringSplitOptions.RemoveEmptyEntries))
            foreach (Match m in Segment.Matches(part))
                out_.Add(m.Groups[1].Success ? m.Groups[1].Value : int.Parse(m.Groups[2].Value, Inv));
        return out_;
    }

    static bool UnsafePath(List<object> segs) => segs.Any(s => s is "__proto__" or "constructor" or "prototype");

    static object? Seg(object s) => s is int i ? (double)i : s;

    /// <summary>The path exists (its value may be null).</summary>
    public static bool HasPath(object? value, object? path)
    {
        var p = Str(path);
        if (p == "" || p == "$") return true;
        var segs = PathSegments(p);
        if (UnsafePath(segs)) return false;
        var cur = value;
        foreach (var s in segs)
        {
            switch (cur)
            {
                case Dictionary<string, object?> d:
                    if (!d.TryGetValue(s is int n ? n.ToString(Inv) : (string)s, out cur)) return false;
                    break;
                case List<object?> l:
                    if (s is "length") cur = (double)l.Count;
                    else if (s is int i && i < l.Count) cur = l[i];
                    else return false;
                    break;
                case string str:
                    if (s is "length") cur = (double)str.Length;
                    else if (s is int j && j < str.Length) cur = str[j].ToString();
                    else return false;
                    break;
                default:
                    return false;
            }
        }
        return true;
    }

    /// <summary>Reads a nested value; null when a step is missing.</summary>
    public static object? GetPath(object? value, object? path)
    {
        var p = Str(path);
        if (p == "" || p == "$") return value;
        var segs = PathSegments(p);
        if (UnsafePath(segs)) return null;
        var cur = value;
        foreach (var s in segs)
        {
            if (cur is null) return null;
            cur = Key(cur, Seg(s));
        }
        return cur;
    }

    sealed class MissingValue { }

    /// <summary>A path that isn't there (JavaScript's undefined): left out of objects, like JSON.stringify does.</summary>
    static readonly object Missing = new MissingValue();

    static object? Lookup(object? value, string path) => HasPath(value, path) ? GetPath(value, path) : Missing;

    static object? Copy(object? v) => v switch
    {
        List<object?> l => new List<object?>(l),
        Dictionary<string, object?> d => new Dictionary<string, object?>(d),
        _ => v,
    };

    /// <summary>A copy with a nested value set.</summary>
    public static object? SetPath(object? value, object? path, object? v)
    {
        var segs = PathSegments(Str(path));
        if (segs.Count == 0) return v;
        object root = value is List<object?> or Dictionary<string, object?> ? Copy(value)! : new Dictionary<string, object?>();
        if (UnsafePath(segs)) return root;
        object cur = root;
        for (var i = 0; i < segs.Count; i++)
        {
            var s = segs[i];
            var last = i == segs.Count - 1;
            if (cur is List<object?> l && s is int n)
            {
                while (l.Count <= n) l.Add(null);
                if (last) { if (!ReferenceEquals(v, Missing)) l[n] = v; break; }
                var next = Copy(l[n]) is var c && c is List<object?> or Dictionary<string, object?> ? c! : segs[i + 1] is int ? new List<object?>() : new Dictionary<string, object?>();
                l[n] = next;
                cur = next;
            }
            else
            {
                var d = cur as Dictionary<string, object?> ?? new Dictionary<string, object?>();
                var k = s is int m ? m.ToString(Inv) : (string)s;
                if (last) { if (!ReferenceEquals(v, Missing)) d[k] = v; break; }
                var next = d.TryGetValue(k, out var x) && Copy(x) is var c && c is List<object?> or Dictionary<string, object?> ? c! : segs[i + 1] is int ? new List<object?>() : new Dictionary<string, object?>();
                d[k] = next;
                cur = next;
            }
        }
        return root;
    }

    static object? Clone(object? v) => v switch
    {
        List<object?> l => l.Select(Clone).ToList(),
        Dictionary<string, object?> d => d.ToDictionary(p => p.Key, p => Clone(p.Value)),
        _ => v,
    };

    /// <summary>A copy without a nested value.</summary>
    public static object? RemovePath(object? value, object? path)
    {
        var segs = PathSegments(Str(path));
        if (segs.Count == 0 || value is not (List<object?> or Dictionary<string, object?>)) return value;
        var clone = Clone(value);
        if (UnsafePath(segs)) return clone;
        var cur = clone;
        foreach (var s in segs.Take(segs.Count - 1))
        {
            object? next = cur switch
            {
                Dictionary<string, object?> map when map.TryGetValue(s is int k ? k.ToString(Inv) : (string)s, out var x) => x,
                List<object?> list when s is int i && i < list.Count => list[i],
                _ => null,
            };
            if (next is not (List<object?> or Dictionary<string, object?>)) return clone;
            cur = next;
        }
        var lastSeg = segs[^1];
        if (cur is List<object?> l && lastSeg is int n) { if (n < l.Count) l.RemoveAt(n); }
        else if (cur is Dictionary<string, object?> d) d.Remove(lastSeg is int m ? m.ToString(Inv) : (string)lastSeg);
        return clone;
    }

    static Dictionary<string, object?> Spread(object? v) => v switch
    {
        Dictionary<string, object?> d => d,
        List<object?> l => l.Select((x, i) => (i, x)).ToDictionary(p => p.i.ToString(Inv), p => p.x),
        string s => s.Select((c, i) => (i, c)).ToDictionary(p => p.i.ToString(Inv), p => (object?)p.c.ToString()),
        _ => new Dictionary<string, object?>(),
    };

    /// <summary>Shallow merge, B over A.</summary>
    public static Dictionary<string, object?> Merge(object? a, object? b)
    {
        var d = new Dictionary<string, object?>(Spread(a));
        foreach (var (k, v) in Spread(b)) d[k] = v;
        return d;
    }

    /// <summary>New object: target path ← source path.</summary>
    public static object? Transform(object? source, object? mapping)
    {
        object? out_ = new Dictionary<string, object?>();
        foreach (var pair in AsArray(mapping))
        {
            var p = AsArray(pair);
            out_ = SetPath(out_, p[0], Lookup(source, Str(p[1])));
        }
        return out_;
    }

    static readonly Regex Placeholder = new(@"\{\{\s*([^}]+?)\s*\}\}", RegexOptions.CultureInvariant);
    static readonly Regex WholePlaceholder = new(@"^\{\{\s*([^}]+?)\s*\}\}$", RegexOptions.CultureInvariant);

    /// <summary>Fills {{path}} placeholders from data.</summary>
    public static object? Template(object? value, object? data)
    {
        var r = Fill(value, data);
        return ReferenceEquals(r, Missing) ? null : r;
    }

    static object? Fill(object? value, object? data)
    {
        switch (value)
        {
            case string s:
                var whole = WholePlaceholder.Match(s);
                if (whole.Success) return Lookup(data, whole.Groups[1].Value);
                return Placeholder.Replace(s, m =>
                {
                    var r = GetPath(data, m.Groups[1].Value);
                    return r is null ? "" : r is List<object?> or Dictionary<string, object?> ? Json(r) : JsString(r);
                });
            case List<object?> l:
                return l.Select(x => Fill(x, data) is var y && ReferenceEquals(y, Missing) ? null : y).ToList();
            case Dictionary<string, object?> d:
                var o = new Dictionary<string, object?>();
                foreach (var (k, x) in d) { var y = Fill(x, data); if (!ReferenceEquals(y, Missing)) o[k] = y; }
                return o;
            default:
                return value;
        }
    }

    /// <summary>JSON.parse that fails with INVALID_JSON.</summary>
    public static object? ParseJson(object? text)
    {
        try { return FddJson.Parse(JsString(text ?? "null")); }
        catch (JsonException) { throw new FddError("INVALID_JSON", "Not valid JSON"); }
    }

    /// <summary>The { code, message } a Catch or Failed pin receives.</summary>
    public static Dictionary<string, object?> ToError(Exception e) => e is FddError f
        ? Obj(("code", f.Code), ("message", f.Message))
        : Obj(("code", "RUNTIME_ERROR"), ("message", e.Message));

    // ---------- strings ----------

    /// <summary>String operand: null → "".</summary>
    public static string Str(object? v) => v is null ? "" : JsString(v);

    /// <summary>String(v), like a Switch compares.</summary>
    public static string AsString(object? v) => JsString(v);

    public static bool Contains(object? text, object? search) => Str(text).Contains(Str(search), StringComparison.Ordinal);

    public static bool StartsWith(object? text, object? prefix) => Str(text).StartsWith(Str(prefix), StringComparison.Ordinal);

    public static bool EndsWith(object? text, object? suffix) => Str(text).EndsWith(Str(suffix), StringComparison.Ordinal);

    public static string Trim(object? text) => Str(text).Trim().Trim('﻿');

    public static string Lower(object? text) => Str(text).ToLowerInvariant();

    public static string Upper(object? text) => Str(text).ToUpperInvariant();

    public static double StrLength(object? text) => Str(text).Length;

    public static string Concat(object? a, object? b) => Str(a) + Str(b);

    public static string ReplaceAll(object? text, object? search, object? replacement)
    {
        var t = Str(text);
        var s = Str(search);
        return s == "" ? string.Join(Str(replacement), t.Select(c => c.ToString())) : t.Replace(s, Str(replacement), StringComparison.Ordinal);
    }

    /// <summary>Empty separator splits on ",".</summary>
    public static List<object?> Split(object? text, object? separator)
    {
        var sep = Str(separator);
        return Str(text).Split(sep == "" ? "," : sep).Select(x => (object?)x).ToList();
    }

    public static string Join(object? items, object? separator) => string.Join(Str(separator), AsArray(items).Select(Str));

    static Regex Rx(string pattern, string flags)
    {
        var o = RegexOptions.None;
        foreach (var c in flags)
        {
            if (!"gimsuyd".Contains(c)) throw new ArgumentException("flags");
            o |= c switch { 'i' => RegexOptions.IgnoreCase, 'm' => RegexOptions.Multiline, 's' => RegexOptions.Singleline, _ => RegexOptions.None };
        }
        // ECMAScript syntax (\d is [0-9]) unless dotAll asks for what it can't combine with
        return new Regex(pattern, (o & RegexOptions.Singleline) == 0 ? o | RegexOptions.ECMAScript : o, TimeSpan.FromSeconds(1));
    }

    public static Dictionary<string, object?> RegexMatch(object? text, object? pattern, object? flags)
    {
        Regex re;
        try { re = Rx(Str(pattern), Str(flags)); }
        catch (ArgumentException) { throw new FddError("INVALID_REGEX", "Invalid pattern " + Str(pattern)); }
        var m = re.Match(Str(text));
        return Obj(("matches", m.Success), ("groups", m.Success ? m.Groups.Cast<Group>().Skip(1).Select(g => g.Success ? (object?)g.Value : null).ToList() : new List<object?>()));
    }

    static readonly Regex Named = new(@"\{(\w+)\}", RegexOptions.ECMAScript);

    /// <summary>Fills {name} placeholders.</summary>
    public static string Format(object? template, object? values) => Named.Replace(Str(template), m => Str(values.Get(m.Groups[1].Value)));

    // ---------- collections ----------

    public static double Len(object? a) => a is List<object?> l ? l.Count : 0;

    public static object? At(object? a, object? index) => Key(AsArray(a), ToNum(index));

    /// <summary>A copy with the item appended.</summary>
    public static List<object?> Append(object? a, object? item) => new(AsArray(a)) { item };

    /// <summary>Deep-equal membership.</summary>
    public static bool Includes(object? a, object? item) => AsArray(a).Any(x => DeepEqual(x, item));

    public static double Sum(object? a, object? path) => AsArray(a).Aggregate(0d, (t, x) => t + ToNum(Str(path) != "" ? GetPath(x, path) : x));

    public static List<object?> SortBy(object? a, object? path, object? desc)
    {
        var dir = B(desc) ? -1 : 1;
        var p = Str(path);
        int Cmp(object? x, object? y)
        {
            object? u = p != "" ? GetPath(x, p) : x, w = p != "" ? GetPath(y, p) : y;
            return Lt(u, w) ? -dir : Lt(w, u) ? dir : 0;
        }
        // a stable sort, like Array.prototype.sort
        return AsArray(a).Select((x, i) => (x, i)).OrderBy(t => t, Comparer<(object? x, int i)>.Create((s, t) => Cmp(s.x, t.x) is var c && c != 0 ? c : s.i.CompareTo(t.i))).Select(t => t.x).ToList();
    }

    /// <summary>Maps with an async function, one item at a time (deterministic order).</summary>
    public static async Task<List<object?>> MapAsync(object? items, Func<object?, object?, Task<object?>> fn)
    {
        var list = AsArray(items);
        var out_ = new List<object?>();
        for (var i = 0; i < list.Count; i++) out_.Add(await fn(list[i], (double)i));
        return out_;
    }

    /// <summary>Filters with an async predicate, one item at a time.</summary>
    public static async Task<List<object?>> FilterAsync(object? items, Func<object?, object?, Task<object?>> fn)
    {
        var list = AsArray(items);
        var out_ = new List<object?>();
        for (var i = 0; i < list.Count; i++) if (Truthy(await fn(list[i], (double)i))) out_.Add(list[i]);
        return out_;
    }

    /// <summary>The first item an async predicate accepts, or null.</summary>
    public static async Task<object?> FindAsync(object? items, Func<object?, object?, Task<object?>> fn)
    {
        var list = AsArray(items);
        for (var i = 0; i < list.Count; i++) if (Truthy(await fn(list[i], (double)i))) return list[i];
        return null;
    }

    /// <summary>True when an async predicate accepts any item (stops at the first).</summary>
    public static async Task<bool> SomeAsync(object? items, Func<object?, object?, Task<object?>> fn)
    {
        var list = AsArray(items);
        for (var i = 0; i < list.Count; i++) if (Truthy(await fn(list[i], (double)i))) return true;
        return false;
    }

    /// <summary>True when an async predicate accepts every item (stops at the first refusal).</summary>
    public static async Task<bool> EveryAsync(object? items, Func<object?, object?, Task<object?>> fn)
    {
        var list = AsArray(items);
        for (var i = 0; i < list.Count; i++) if (!Truthy(await fn(list[i], (double)i))) return false;
        return true;
    }

    /// <summary>The first item, or null.</summary>
    public static object? First(object? a) => AsArray(a) is { Count: > 0 } l ? l[0] : null;

    /// <summary>The last item, or null.</summary>
    public static object? Last(object? a) => AsArray(a) is { Count: > 0 } l ? l[^1] : null;

    /// <summary>Items grouped by the text of a path: { value: [items] }, keys in JavaScript's order.</summary>
    public static Dictionary<string, object?> GroupBy(object? a, object? path)
    {
        var p = Str(path);
        var groups = new Dictionary<string, object?>();
        foreach (var x in AsArray(a))
        {
            var k = ToStringValue(p != "" ? GetPath(x, p) : x);
            if (!groups.TryGetValue(k, out var g)) groups[k] = g = new List<object?>();
            ((List<object?>)g!).Add(x);
        }
        return KeyList(groups).ToDictionary(k => k, k => groups[k]);
    }

    /// <summary>The mean of numbers or of a path; 0 for an empty list.</summary>
    public static double Average(object? a, object? path) => AsArray(a).Count is var n && n > 0 ? Sum(a, path) / n : 0;

    // ---------- validation: every check returns { valid, message } ----------

    static Dictionary<string, object?> Valid() => Obj(("valid", true), ("message", ""));

    static Dictionary<string, object?> Invalid(string message) => Obj(("valid", false), ("message", message));

    public static Dictionary<string, object?> CheckRequired(object? v, object? field) => IsEmpty(v) ? Invalid(Str(field) + " is required") : Valid();

    static readonly Regex Email = new(@"^[^@\s]+@[^@\s]+\.[^@\s]+$", RegexOptions.ECMAScript);

    public static Dictionary<string, object?> CheckEmail(object? v, object? field) => v is string s && Email.IsMatch(s) ? Valid() : Invalid(Str(field) + " must be a valid email");

    static string ValueType(object? v) => v switch
    {
        null => "null",
        List<object?> => "array",
        double d => double.IsFinite(d) && Math.Floor(d) == d ? "integer" : "number",
        string => "string",
        bool => "boolean",
        _ => "object",
    };

    public static Dictionary<string, object?> CheckType(object? v, object? type, object? field)
    {
        var vt = ValueType(v);
        var t = Str(type);
        return vt == t || (t == "number" && vt == "integer") ? Valid() : Invalid(Str(field) + " must be " + t);
    }

    /// <summary>First problem of a value against a shape, or null.</summary>
    public static string? CheckValue(object? v, object? s, string path)
    {
        if (s is not Dictionary<string, object?> shape || Eq(shape.Get("type"), "any")) return null;
        var type = shape.Get("type");
        if (v is null) return B(shape.Get("nullable")) || Eq(type, "null") ? null : path + " is null";
        var t = ValueType(v);
        if (Eq(type, "number") && (t == "integer" || t == "number")) return null;
        if (!Eq(type, t)) return path + ": expected " + Str(type) + ", got " + t;
        if (shape.Get("enum") is List<object?> en && en.Count > 0 && !en.Any(x => DeepEqual(x, v))) return path + ": " + Json(v) + " is not one of " + string.Join(", ", en.Select(JsString));
        if (t == "object" && shape.Get("properties") is Dictionary<string, object?> props)
        {
            var o = (Dictionary<string, object?>)v;
            foreach (var (k, f) in props)
            {
                if (!o.TryGetValue(k, out var child))
                {
                    if (B(f.Get("required"))) return path + "." + k + " is missing";
                    continue;
                }
                var p = CheckValue(child, f, path + "." + k);
                if (p != null) return p;
            }
        }
        if (t == "array")
        {
            var l = (List<object?>)v;
            for (var i = 0; i < l.Count; i++)
            {
                var p = CheckValue(l[i], shape.Get("items"), path + "[" + i.ToString(Inv) + "]");
                if (p != null) return p;
            }
        }
        return null;
    }

    public static Dictionary<string, object?> CheckShape(object? v, object? shape, object? field) => CheckValue(v, shape, Str(field)) is string p ? Invalid(p) : Valid();

    public static Dictionary<string, object?> CheckRange(object? v, object? min, object? max, object? field)
    {
        var n = ToNum(v);
        if (v is not double) return Invalid(Str(field) + " must be a number");
        if (min is not null && !Eq(min, "") && n < ToNum(min)) return Invalid(Str(field) + " must be ≥ " + JsString(min));
        if (max is not null && !Eq(max, "") && n > ToNum(max)) return Invalid(Str(field) + " must be ≤ " + JsString(max));
        return Valid();
    }

    public static Dictionary<string, object?> CheckRegex(object? v, object? pattern, object? field)
    {
        try { return Rx(Str(pattern), "").IsMatch(Str(v)) ? Valid() : Invalid(Str(field) + " has an invalid format"); }
        catch (ArgumentException) { return Invalid("invalid pattern"); }
    }

    public static Dictionary<string, object?> CheckPassword(object? v, object? policy, object? field)
    {
        var p = Str(v);
        var min = ToNum(policy.Get("minLength"));
        if (p.Length < min) return Invalid(Str(field) + " must be at least " + NumText(min) + " characters");
        if (B(policy.Get("requireDigit")) && !p.Any(char.IsAsciiDigit)) return Invalid(Str(field) + " must contain a digit");
        if (B(policy.Get("requireUpper")) && !p.Any(char.IsAsciiLetterUpper)) return Invalid(Str(field) + " must contain an uppercase letter");
        return Valid();
    }

