    // ---------- math ----------

    /// <summary>Rounds to 0–15 decimals, halves up.</summary>
    public static double Round(object? v, object? decimals)
    {
        var x = ToNum(v);
        var d = Math.Truncate(ToNum(decimals));
        var f = Math.Pow(10, double.IsFinite(d) ? Math.Min(15, Math.Max(0, d)) : 0);
        var y = x * f + 0.5;
        return double.IsFinite(y) ? Math.Floor(y) / f : x;
    }

    public static double Floor(object? v) => Math.Floor(ToNum(v));

    public static double Ceil(object? v) => Math.Ceiling(ToNum(v));

    public static double Abs(object? v) => Math.Abs(ToNum(v));

    public static double Min(object? a, object? b) => Math.Min(ToNum(a), ToNum(b));

    public static double Max(object? a, object? b) => Math.Max(ToNum(a), ToNum(b));

    /// <summary>The value kept between lo and hi.</summary>
    public static double Clamp(object? v, object? lo, object? hi) => Math.Min(Math.Max(ToNum(v), ToNum(lo)), ToNum(hi));

    /// <summary>JavaScript's ** (1 ** Infinity is NaN).</summary>
    public static double Power(object? a, object? b)
    {
        double x = ToNum(a), y = ToNum(b);
        return double.IsNaN(y) || (Math.Abs(x) == 1 && double.IsInfinity(y)) ? double.NaN : Math.Pow(x, y);
    }

    public static double Sqrt(object? v) => Math.Sqrt(ToNum(v));

    // ---------- text and encoding ----------

    /// <summary>A slice position: negative counts from the end, clamped to 0…n.</summary>
    static int RelIndex(object? v, int n)
    {
        var r = Math.Truncate(ToNum(v));
        if (double.IsNaN(r)) return 0;
        return r < 0 ? (int)Math.Max(n + r, 0) : (int)Math.Min(r, n);
    }

    /// <summary>Like String.prototype.slice; a null end means the end of the text.</summary>
    public static string Substring(object? text, object? start, object? end)
    {
        var t = Str(text);
        int i = RelIndex(start, t.Length), j = end is null ? t.Length : RelIndex(end, t.Length);
        return j > i ? t[i..j] : "";
    }

    public static double IndexOf(object? text, object? search) => Str(text).IndexOf(Str(search), StringComparison.Ordinal);

    static string PadText(object? text, object? length, object? fill, bool atStart)
    {
        var t = Str(text);
        var n = Math.Truncate(ToNum(length));
        if (n > 100000) throw new FddError("INVALID_LENGTH", "Length must be at most 100000");
        var f = fill is null ? " " : Str(fill);
        if (double.IsNaN(n) || n <= t.Length || f.Length == 0) return t;
        var need = (int)n - t.Length;
        var sb = new StringBuilder();
        while (sb.Length < need) sb.Append(f);
        var pad = sb.ToString(0, need);
        return atStart ? pad + t : t + pad;
    }

    public static string PadStart(object? text, object? length, object? fill) => PadText(text, length, fill, true);

    public static string PadEnd(object? text, object? length, object? fill) => PadText(text, length, fill, false);

    /// <summary>UTF-8 text as Base64.</summary>
    public static string Base64Encode(object? text) => Convert.ToBase64String(Encoding.UTF8.GetBytes(Str(text)));

    /// <summary>Fixed decimals (halves up) and a thousands separator; fails with INVALID_NUMBER.</summary>
    public static string FormatNumber(object? value, object? decimals, object? thousands, object? point)
    {
        var d0 = Math.Truncate(ToNum(decimals));
        var d = double.IsFinite(d0) ? (int)Math.Min(15, Math.Max(0, d0)) : 0;
        var r = Round(value, (double)d);
        if (!double.IsFinite(r) || Math.Abs(r) >= 1e21) throw new FddError("INVALID_NUMBER", "Not a number that can be formatted");
        var text = Math.Abs(r).ToString("F" + d, Inv);
        var dot = text.IndexOf('.');
        string whole = dot < 0 ? text : text[..dot], frac = dot < 0 ? "" : text[(dot + 1)..];
        var sign = r < 0 && (whole + frac).Any(c => c >= '1' && c <= '9') ? "-" : "";
        var groups = new List<string>();
        while (whole.Length > 3)
        {
            groups.Insert(0, whole[^3..]);
            whole = whole[..^3];
        }
        groups.Insert(0, whole);
        return sign + string.Join(Str(thousands), groups) + (frac != "" ? Str(point) + frac : "");
    }

    /// <summary>sha256, sha1 or md5 ("SHA-256" too); fails with INVALID_ALGORITHM.</summary>
    static string DigestAlgorithm(object? a)
    {
        var k = Str(a).Trim().ToLowerInvariant().Replace("-", "");
        if (k is not ("sha256" or "sha1" or "md5")) throw new FddError("INVALID_ALGORITHM", "Unknown hash algorithm \"" + Str(a) + "\" (use sha256, sha1 or md5)");
        return k;
    }

    /// <summary>hex or base64; fails with INVALID_ENCODING.</summary>
    static string EncodeDigest(byte[] b, object? encoding)
    {
        var e = Str(encoding).Trim().ToLowerInvariant();
        if (e == "hex") return Convert.ToHexString(b).ToLowerInvariant();
        if (e == "base64") return Convert.ToBase64String(b);
        throw new FddError("INVALID_ENCODING", "Unknown encoding \"" + Str(encoding) + "\" (use hex or base64)");
    }

    /// <summary>SHA-256, SHA-1 or MD5 of UTF-8 text, as hex or Base64.</summary>
    public static string Hash(object? text, object? algorithm, object? encoding)
    {
        var alg = DigestAlgorithm(algorithm);
        var m = Encoding.UTF8.GetBytes(Str(text));
        var b = alg == "sha256" ? System.Security.Cryptography.SHA256.HashData(m) : alg == "sha1" ? System.Security.Cryptography.SHA1.HashData(m) : System.Security.Cryptography.MD5.HashData(m);
        return EncodeDigest(b, encoding);
    }

    /// <summary>HMAC of UTF-8 text with a UTF-8 key, as hex or Base64.</summary>
    public static string Hmac(object? text, object? key, object? algorithm, object? encoding)
    {
        var alg = DigestAlgorithm(algorithm);
        byte[] k = Encoding.UTF8.GetBytes(Str(key)), m = Encoding.UTF8.GetBytes(Str(text));
        var b = alg == "sha256" ? System.Security.Cryptography.HMACSHA256.HashData(k, m) : alg == "sha1" ? System.Security.Cryptography.HMACSHA1.HashData(k, m) : System.Security.Cryptography.HMACMD5.HashData(k, m);
        return EncodeDigest(b, encoding);
    }

    /// <summary>Base64 to UTF-8 text; fails with INVALID_BASE64.</summary>
    public static string Base64Decode(object? text)
    {
        var t = Regex.Replace(Str(text), "[\t\n\f\r ]+", "");
        if (t.Length % 4 == 0) t = Regex.Replace(t, @"={1,2}\z", "");
        if (t.Length % 4 == 1 || !Regex.IsMatch(t, @"^[A-Za-z0-9+/]*\z")) throw new FddError("INVALID_BASE64", "Not valid Base64");
        try { return Encoding.UTF8.GetString(Convert.FromBase64String(t + new string('=', (4 - t.Length % 4) % 4))); }
        catch (FormatException) { throw new FddError("INVALID_BASE64", "Not valid Base64"); }
    }

    /// <summary>encodeURIComponent.</summary>
    public static string UrlEncode(object? text)
    {
        var sb = new StringBuilder();
        foreach (var b in Encoding.UTF8.GetBytes(Str(text)))
        {
            var c = (char)b;
            if (char.IsAsciiLetterOrDigit(c) || "-_.!~*'()".Contains(c)) sb.Append(c);
            else sb.Append('%').Append(b.ToString("X2", Inv));
        }
        return sb.ToString();
    }

    static readonly UTF8Encoding StrictUtf8 = new(false, true);

    /// <summary>decodeURIComponent; fails with INVALID_URL_ENCODING.</summary>
    public static string UrlDecode(object? text)
    {
        var s = Str(text);
        var sb = new StringBuilder();
        var buf = new List<byte>();
        try
        {
            for (var i = 0; i < s.Length;)
            {
                if (s[i] == '%')
                {
                    if (i + 2 >= s.Length || !char.IsAsciiHexDigit(s[i + 1]) || !char.IsAsciiHexDigit(s[i + 2])) throw new FormatException();
                    buf.Add(Convert.ToByte(s.Substring(i + 1, 2), 16));
                    i += 3;
                    continue;
                }
                if (buf.Count > 0) { sb.Append(StrictUtf8.GetString(buf.ToArray())); buf.Clear(); }
                sb.Append(s[i]);
                i++;
            }
            if (buf.Count > 0) sb.Append(StrictUtf8.GetString(buf.ToArray()));
        }
        catch (Exception e) when (e is FormatException or ArgumentException)
        {
            throw new FddError("INVALID_URL_ENCODING", "Not valid URL encoding");
        }
        return sb.ToString();
    }

    // ---------- records and lists ----------

    static readonly Regex IndexKey = new(@"^(0|[1-9][0-9]*)\z", RegexOptions.CultureInvariant);

    static bool IsIndexKey(string k) => IndexKey.IsMatch(k) && double.Parse(k, Inv) < 4294967295;

    static List<string> KeyList(object? o) => o is Dictionary<string, object?> d
        ? d.Keys.Where(IsIndexKey).OrderBy(k => double.Parse(k, Inv)).Concat(d.Keys.Where(k => !IsIndexKey(k))).ToList()
        : new List<string>();

    /// <summary>Field names in JavaScript's order: integer-like keys ascending, then the rest as inserted.</summary>
    public static List<object?> Keys(object? o) => KeyList(o).Select(k => (object?)k).ToList();

    public static List<object?> Values(object? o) => KeyList(o).Select(k => ((Dictionary<string, object?>)o!)[k]).ToList();

    public static List<object?> Entries(object? o) => KeyList(o).Select(k => (object?)Obj(("key", k), ("value", ((Dictionary<string, object?>)o!)[k]))).ToList();

    /// <summary>Like Array.prototype.slice; a null end means the end of the list.</summary>
    public static List<object?> Slice(object? a, object? start, object? end)
    {
        var l = AsArray(a);
        int i = RelIndex(start, l.Count), j = end is null ? l.Count : RelIndex(end, l.Count);
        return j > i ? l.GetRange(i, j - i) : new List<object?>();
    }

    public static List<object?> Reverse(object? a) => Enumerable.Reverse(AsArray(a)).ToList();

    /// <summary>Deep-equal duplicates removed, first kept.</summary>
    public static List<object?> Unique(object? a)
    {
        var out_ = new List<object?>();
        foreach (var x in AsArray(a)) if (!out_.Any(y => DeepEqual(x, y))) out_.Add(x);
        return out_;
    }

    /// <summary>Deep-equal position, or -1.</summary>
    public static double ItemIndex(object? a, object? item) => AsArray(a).FindIndex(x => DeepEqual(x, item));

    /// <summary>One level.</summary>
    public static List<object?> Flatten(object? a) => AsArray(a).SelectMany(x => x as List<object?> ?? new List<object?> { x }).ToList();

    // ---------- dates: ISO 8601 text in UTC; numbers are epoch milliseconds ----------

    const long MinMs = -62167219200000, MaxMs = 253402300799999, DayMs = 86400000;
    static readonly Regex DateText = new(@"^([0-9]{4})-([0-9]{2})-([0-9]{2})(?:[Tt ]([0-9]{2}):([0-9]{2})(?::([0-9]{2})(?:\.([0-9]+))?)?)?(?:([Zz])|([+-])([0-9]{2}):?([0-9]{2}))?\z", RegexOptions.CultureInvariant);
    static readonly string[] TimeUnits = { "millisecond", "milliseconds", "ms", "second", "seconds", "minute", "minutes", "hour", "hours", "day", "days", "week", "weeks", "month", "months", "year", "years" };
    static readonly long[] TimeUnitMs = { 1, 1, 1, 1000, 1000, 60000, 60000, 3600000, 3600000, DayMs, DayMs, 7 * DayMs, 7 * DayMs, -1, -1, -12, -12 };
    static readonly string[] MonthNames = { "January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December" };
    static readonly string[] DayNames = { "Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday" };
    static readonly string[] DateTokens = { "yyyy", "yy", "MMMM", "MMM", "MM", "M", "dd", "d", "EEEE", "EEE", "HH", "H", "hh", "h", "mm", "m", "ss", "s", "SSS", "a" };

    static long FloorDiv(long a, long b) => a / b - (a % b != 0 && (a < 0) != (b < 0) ? 1 : 0);

    /// <summary>Days since 1970-01-01 (proleptic Gregorian).</summary>
    static long DaysFromCivil(long y, long m, long d)
    {
        y -= m <= 2 ? 1 : 0;
        long era = FloorDiv(y, 400), yoe = y - era * 400;
        var doy = (153 * (m + (m > 2 ? -3 : 9)) + 2) / 5 + d - 1;
        return era * 146097 + yoe * 365 + yoe / 4 - yoe / 100 + doy - 719468;
    }

    static (long Y, long M, long D) CivilFromDays(long z)
    {
        z += 719468;
        long era = FloorDiv(z, 146097), doe = z - era * 146097;
        var yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
        var doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
