        var m = mp + (mp < 10 ? 3 : -9);
        return (yoe + era * 400 + (m <= 2 ? 1 : 0), m, doy - (153 * mp + 2) / 5 + 1);
    }

    static long DaysIn(long y, long m) => m == 2 ? (y % 4 == 0 && (y % 100 != 0 || y % 400 == 0) ? 29 : 28) : m is 4 or 6 or 9 or 11 ? 30 : 31;

    /// <summary>Epoch milliseconds of a date (years 0–9999), or null.</summary>
    static long? DateMs(object? v)
    {
