        if (v is double x)
        {
            if (!double.IsFinite(x) || Math.Truncate(x) < MinMs || Math.Truncate(x) > MaxMs) return null;
            ms = (long)Math.Truncate(x);
        }
        else if (v is string s)
        {
            var m = DateText.Match(s.Trim().Trim('﻿'));
            if (!m.Success) return null;
            long G(int k) => m.Groups[k].Success ? long.Parse(m.Groups[k].Value, Inv) : 0;
            long y = G(1), mo = G(2), d = G(3), h = G(4), mi = G(5), sec = G(6);
            if (mo < 1 || mo > 12 || d < 1 || d > DaysIn(y, mo) || h > 23 || mi > 59 || sec > 59) return null;
            var tz = m.Groups[9].Success;
            if (tz && (G(10) > 23 || G(11) > 59)) return null;
