    static long NeedDate(object? v) => DateMs(v) ?? throw new FddError("INVALID_DATE", "Not a valid date");

    /// <summary>[year, month, day, hour, minute, second, millisecond, weekday (0 = Sunday), time of day].</summary>
    static long[] DateFields(long ms)
    {
        var days = FloorDiv(ms, DayMs);
        var t = ms - days * DayMs;
        var (y, m, d) = CivilFromDays(days);
        return new[] { y, m, d, t / 3600000, t / 60000 % 60, t / 1000 % 60, t % 1000, (days % 7 + 11) % 7, t };
    }

    static string IsoDate(double ms)
    {
        if (!(ms >= MinMs && ms <= MaxMs)) throw new FddError("INVALID_DATE", "The date is out of range");
        var p = DateFields((long)ms);
        return string.Create(Inv, $"{p[0]:D4}-{p[1]:D2}-{p[2]:D2}T{p[3]:D2}:{p[4]:D2}:{p[5]:D2}.{p[6]:D3}Z");
    }

    /// <summary>Milliseconds of a unit; months are -1 and years -12.</summary>
    static long TimeUnit(object? u)
    {
        var i = Array.IndexOf(TimeUnits, Str(u).Trim().ToLowerInvariant());
        if (i < 0) throw new FddError("INVALID_UNIT", "Unknown time unit \"" + Str(u) + "\"");
        return TimeUnitMs[i];
    }

    /// <summary>A date as UTC date-time text and epoch milliseconds.</summary>
    public static Dictionary<string, object?> ParseDate(object? v) => DateMs(v) is long ms
        ? Obj(("date", IsoDate(ms)), ("timestamp", (double)ms), ("valid", true))
        : Obj(("date", null), ("timestamp", null), ("valid", false));

    /// <summary>yyyy yy MMMM MMM MM M dd d EEEE EEE HH H hh h mm m ss s SSS a; 'quoted' text is kept, '' is a quote (inside quotes too).</summary>
    public static string FormatDate(object? date, object? pattern)
    {
