        string Z(long n, int w) => n.ToString(new string('0', w), Inv);
        var values = new[] { Z(p[0], 4), Z(p[0] % 100, 2), month, month[..3], Z(p[1], 2), Z(p[1], 1), Z(p[2], 2), Z(p[2], 1), day, day[..3],
            Z(p[3], 2), Z(p[3], 1), Z(h12, 2), Z(h12, 1), Z(p[4], 2), Z(p[4], 1), Z(p[5], 2), Z(p[5], 1), Z(p[6], 3), p[3] < 12 ? "AM" : "PM" };
