    /// <summary>Whole units from From to To, toward zero.</summary>
    public static double TimeBetween(object? from, object? to, object? unit)
    {
        long a = NeedDate(from), b = NeedDate(to), u = TimeUnit(unit);
        if (u > 0) return Math.Truncate((double)(b - a) / u) + 0.0;
        var p = DateFields(a);
        var q = DateFields(b);
        var months = (q[0] - p[0]) * 12 + q[1] - p[1];
        if (months > 0 && (q[2] < p[2] || (q[2] == p[2] && q[8] < p[8]))) months--;
        else if (months < 0 && (q[2] > p[2] || (q[2] == p[2] && q[8] > p[8]))) months++;
        return Math.Truncate((double)months / -u) + 0.0;
