    /// <summary>year … millisecond in UTC, weekday 1 = Monday … 7 = Sunday.</summary>
    public static Dictionary<string, object?> DateParts(object? date)
    {
        var p = DateFields(NeedDate(date));
        return Obj(("year", (double)p[0]), ("month", (double)p[1]), ("day", (double)p[2]), ("hour", (double)p[3]), ("minute", (double)p[4]),
            ("second", (double)p[5]), ("millisecond", (double)p[6]), ("weekday", p[7] == 0 ? 7d : p[7]));
    }

    /// <summary>A UTC date-time from its parts; fails with INVALID_DATE.</summary>
    public static string MakeDate(object? year, object? month, object? day, object? hour, object? minute, object? second)
    {
