        if (!v.All(x => double.IsFinite(x) && Math.Floor(x) == x)) throw new FddError("INVALID_DATE", "Not a valid date");
        long y = (long)v[0], m = (long)v[1], d = (long)v[2], h = (long)v[3], mi = (long)v[4], s = (long)v[5];
