            throw new FddError("INVALID_DATE", "Not a valid date");
        return IsoDate((DaysFromCivil(y, m, d) * 86400 + h * 3600 + mi * 60 + s) * 1000);
    }

    static readonly string[] Periods = { "hour", "hours", "day", "days", "week", "weeks", "month", "months", "year", "years" };

    /// <summary>First (or last) millisecond of the hour, day, week from Monday, month or year; fails with INVALID_UNIT.</summary>
    static string PeriodEdge(object? date, object? unit, bool end)
    {
        var ms = NeedDate(date);
        var p = DateFields(ms);
        var day = FloorDiv(ms, DayMs) * DayMs;
        var u = Array.IndexOf(Periods, Str(unit).Trim().ToLowerInvariant());
        if (u < 0) throw new FddError("INVALID_UNIT", "Unknown period \"" + Str(unit) + "\" (use hour, day, week, month or year)");
        var (from, length) = (u / 2) switch
        {
            0 => (ms - p[8] % 3600000, 3600000L),
            1 => (day, DayMs),
            2 => (day - (p[7] + 6) % 7 * DayMs, 7 * DayMs),
            3 => (DaysFromCivil(p[0], p[1], 1) * DayMs, DaysIn(p[0], p[1]) * DayMs),
            _ => (DaysFromCivil(p[0], 1, 1) * DayMs, (DaysFromCivil(p[0] + 1, 1, 1) - DaysFromCivil(p[0], 1, 1)) * DayMs),
        };
        return IsoDate(end ? from + length - 1 : from);
    }

    /// <summary>The first moment of the period the date is in (UTC).</summary>
    public static string StartOf(object? date, object? unit) => PeriodEdge(date, unit, false);

    /// <summary>The last moment (…:59.999) of the period the date is in (UTC).</summary>
    public static string EndOf(object? date, object? unit) => PeriodEdge(date, unit, true);

    // ---------- runtime ----------

    /// <summary>Current date-time (ISO, like JavaScript's toISOString).</summary>
    public static string Now() => DateTime.UtcNow.ToString("yyyy-MM-dd'T'HH:mm:ss.fff'Z'", Inv);

    public static string Uuid() => Guid.NewGuid().ToString();

    /// <summary>Integer between min and max.</summary>
    public static double Random(object? min, object? max)
    {
        double lo = ToNum(min), hi = ToNum(max);
        return Math.Floor(lo + Rng.NextDouble() * (hi - lo + 1));
    }

    public static void Log(object? message) => Console.WriteLine(message is string s ? s : Json(message));

    public static Task Sleep(object? ms) => Task.Delay(TimeSpan.FromMilliseconds(Math.Max(0, ToNum(ms))));

    /// <summary>Runs branches concurrently and waits for all.</summary>
    public static Task Parallel(params Func<Task>[] branches) => Task.WhenAll(branches.Select(b => b()));
}

